import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Searchable security","description":"","frontmatter":{},"headers":[],"relativePath":"searchable/security.md","filePath":"searchable/security.md","lastUpdated":1793126588000}'),o={name:"searchable/security.md"};function n(i,e,c,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="searchable-security" tabindex="-1">Searchable security <a class="header-anchor" href="#searchable-security" aria-label="Permalink to &quot;Searchable security&quot;">​</a></h1><p>Searchable treats tool input, remote responses, canonical files, disposable caches, and model context as untrusted.</p><p>The default HTTP client accepts HTTP and HTTPS targets without user information. Before connecting, it resolves every address and rejects the request if any answer is local, private, link-local, metadata, multicast, reserved, or otherwise non-public. It pins an accepted answer for the connection. Redirects receive the same checks; HTTPS downgrade, loops, and excessive hops fail. Cross-origin redirects lose sensitive headers.</p><p>The client counts decoded response bytes and destroys an oversized stream. Ollama responses use incremental newline-delimited JSON parsing with separate frame and answer bounds. One overall fetch deadline covers the configured strategy sequence, and each attempt uses the smaller per-strategy deadline. The runtime converts public epoch deadlines once and uses monotonic timers for network, storage, cache, and migration work. Cancellation stops network reads and prevents later publication.</p><p>Jina and Wayback receive the requested URL only when it has no user information or query string. Wayback snapshot URLs must use the expected HTTPS archive host. Ollama is a narrow trusted-local exception used only by <code>web_ask</code>; <code>web_fetch</code> cannot use it to reach local services.</p><p>Canonical stash files are repository authority. Repository Store rejects symlinks, hard links, special files, unsafe paths, concurrent replacements, and quota violations. SQLite contains only a derived FTS projection. Its separate disk limit allows eight times the canonical quota plus 8 MiB for SQLite and rebuild overhead. Grep reloads matching canonical files and builds returned snippets from those files.</p><p>Ask prompts mark page content as untrusted quoted data and cap the complete prompt in UTF-8 bytes. This framing does not make remote text or model answers trustworthy. Verify important claims against their returned source URLs.</p><p>Error redaction removes resolved provider credentials and URL queries from diagnostic text. Do not log prompts, page bodies, request headers, transport objects, or upstream response bodies.</p>',8)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
